const description = trigger.payload.item.description ?? "";
// "Mirror Linear tasks to Todoist" starts the description with [LEON-123](https://linear.app/<workspace>/issue/LEON-123/<slug>).
// Only that first-line link counts: other tasks link to Linear issues that completing them does not finish.
const match = description.match(/^\[([A-Z][A-Z0-9]*-\d+)\]\(https:\/\/linear\.app\/[^/\s]+\/issue\/([A-Z][A-Z0-9]*-\d+)[/)]/);
const linearRef = match && match[1] === match[2] ? match[1] : "";
return {
  linearRef,
  matchCount: linearRef ? 1 : 0
};

const ref = steps.completeLinearIssue.issueIdentifier;
const text = {
  completed: `Marked ${ref} as Done in Linear.`,
  alreadyClosed: `${ref} was already closed in Linear; left it as it was.`,
  notFound: `Found no Linear issue ${ref}; changed nothing.`
}[steps.completeLinearIssue.outcome];
return { text };
